 function chart(){var xs=Array.isArray(S.months)?S.months:[],max=Math.max(0,...xs.flatMap(function(x){return [Number(x.revenueMinor||0),Number(x.expenseMinor||0)];}));if(!xs.length)return '<div class="empty-state"><h3>'+esc(t('noReport'))+'</h3></div>';return '<div class="chart-card"><div class="card-heading"><h2>'+esc(t('monthly'))+'</h2><span class="chart-legend"><span><i class="legend-dot"></i>'+esc(t('income'))+'</span><span><i class="legend-dot gold"></i>'+esc(t('expense'))+'</span></span></div><div class="bars" role="img" aria-label="'+esc(t('monthly'))+'">'+xs.slice(-8).map(function(x){var a=max?Math.max(2,Number(x.revenueMinor)*130/max):2,b=max?Math.max(2,Number(x.expenseMinor)*130/max):2;return '<div class="bar-pair" title="'+esc(x.month)+'"><span class="bar" style="height:'+a+'px"></span><span class="bar expense" style="height:'+b+'px"></span></div>';}).join('')+'</div><div class="chart-labels">'+xs.slice(-8).map(function(x){return '<span>'+esc(x.month.slice(5))+'/'+esc(x.month.slice(2,4))+'</span>';}).join('')+'</div></div>';}
 function taxAmount(){var d=S.review?.authoritativeDetermination||S.position?.scopePosition?.taxCalculation?.result||{},m=d.taxAmount||d.netTaxPayable||d.amount;return m&&m.amountMinor!=null?money(m.amountMinor,m.currency):null;} function readiness(){var items=[{ok:Boolean(S.ws?.activated),a:t('business'),b:S.ws?.activated?t('ready'):t('emptyProfile')},{ok:Boolean(S.ws?.taxReady),a:t('ruleCoverage'),b:S.ws?.countryPackResolution?.status||t('needsReview')},{ok:Boolean(S.review?.taxReady&&taxAmount()),a:t('taxEstimate'),b:t('taxReview')}],n=items.filter(function(x){return x.ok;}).length;return '<section class="card readiness-card"><div class="card-heading"><h2>'+e(t('readiness'))+'</h2><button class="icon-button" data-page="tax" aria-label="'+e(t('viewAll'))+'">›</button></div><div class="readiness-score"><div class="readiness-ring" style="--readiness-angle:'+(n/3*360)+'deg"><strong>'+n+'/3</strong></div><div class="readiness-copy"><strong>'+e(n===3?t('taxAvailable'):t('taxReview'))+'</strong><p>'+e(t('taxConditional'))+'</p></div></div><div class="readiness-list">'+items.map(function(x){return '<div class="readiness-item '+(x.ok?'done':'')+'"><span>'+e(x.a+' · '+x.b)+'</span></div>';}).join('')+'</div><button class="button button-secondary" data-page="tax">'+e(t('readiness'))+'</button></section>';}
